      with SbtModule with Cross.Module[String] {
    def scalaVersion: T[String] = T(v.scalaVersions(crossValue))
    def scalaReflectIvy = v.scalaReflect(crossValue)
  }

  object hardfloat extends Cross[Hardfloat](crossValue)
