package config

object config {

  /** Superclass of all Parameter keys
    * @param default Optional default value, if a query with this key is not found
    */
  abstract class Field[T] private (val default: Option[T]) {
    def this() = this(None)
    def this(default: T) = this(Some(default))
  }

  /** Super class of all Parameter classes. Defines basic querying APIs.
    */
  abstract class View {

    /** Looks up a parameter name within this view to obtain the corresponding value
      * Throws an error if the parameter value is not found
      *
      * @param pname name of the parameter
      * @tparam T the type of the returned value
      * @return the returned value
      */
    final def apply[T](pname: Field[T]): T = {
      val out = find(pname)
      require(out.isDefined, s"Key ${pname} is not defined in Parameters")
      out.get
    }

    // We need to leave this in until all submodules can be bumped
    @deprecated(
      "up(XYZ, site) is no longer necessary; remove the superfluous site argument",
      "CDE 0.1"
    )
    final def apply[T](pname: Field[T], ignore: View): T = apply(pname)

    /** Looks up a parameter name in `this` view to obtain the corresponding value
      * If found, returns Some(value), otherwise returns None
      *
      * @param pname name of the parameter
      * @tparam T the type of the returned value
      * @return the returned value
      */
    final def lift[T](pname: Field[T]): Option[T] = find(pname)

    // All queries start here
    protected[config] def find[T](pname: Field[T]): Option[T]
  }

  /** Parameters are chain-able views, which can be strung together like a linked list.
    * A query will start at the head of the list; if not found, will go to the next parameter object, up, to
    * continue the query.
    */
  abstract class Parameters extends View {

    /** Create a new Parameters object, when queried, searches first in the rhs Parameters. If no value is found, then
      * continue search in this Parameters. Note that this is an immutable operation, creating a new Parameters object.
      * Neither `this` nor `rhs` are modified by this function.
      *
      * e.g. val z = x.alter(y) // z settings are the settings in 'y', then the settings in 'x'
      *
      * @param rhs Parameters to first search in, 'altering' the settings of this Parameters
      * @return a new Parameters object whose settings are first the rhs, then this.
      */
    final def alter(rhs: Parameters): Parameters =
      new ChainParameters(rhs, this)

    /** Create a new Parameters object, when queried, searches first in the `f` function. If no value is found, then
      * continue search in `this`. Parameters. Note that this is an immutable operation, creating a new Parameters object.
      * Neither `this` nor `f` are modified by this function.
      *
      * e.g. val z = x.alter(y) // z settings are the settings in 'y', then the settings in 'x'
      *
      * @param f A function to first search in
      * @return a new Parameters object whose settings are first the `f`, then `this`
      */
    final def alter(
      f: (View, View, View) => PartialFunction[Any, Any]
    ): Parameters =
      alter(Parameters(f))

    /** Create a new Parameters object, when queried, searches first in the `f` partial function. If no value is found,
      * then continue search in `this`. Parameters. Note that this is an immutable operation, creating a new Parameters
      * object. Neither `this` nor `f` are modified by this function.
      *
      * e.g. val z = x.alter(y) // z settings are the settings in 'y', then the settings in 'x'
      *
      * @param f A function to first search in
      * @return a new Parameters object whose settings are first the `f`, then `this`
      */
    final def alterPartial(f: PartialFunction[Any, Any]): Parameters =
      alter(Parameters((_, _, _) => f))

    /** Create a new Parameters object, when queried, searches first in the map. If no value is found,
      * then continue search in `this`. Parameters. Note that this is an immutable operation, creating a new Parameters
      * object. Neither `this` nor `m` are modified by this function.
      *
      * e.g. val z = x.alterMap(y) // z settings are the settings in 'y', then the settings in 'x'
      *
      * @param m a map containing parameters
      * @return a new Parameters object whose settings are first the `f`, then `this`
      */
    final def alterMap(m: Map[Any, Any]): Parameters =
      alter(new MapParameters(m))

    protected[config] def chain[T](
      site:  View,
      here:  View,
      up:    View,
      pname: Field[T]
    ): Option[T]
    protected[config] def find[T](pname: Field[T]): Option[T] =
      chain(this, this, new TerminalView, pname)

    // x orElse y: settings in 'x' overrule settings in 'y'
    final def orElse(x: Parameters): Parameters = x.alter(this)

    /** DEPRECATED!!!
      * Please replace `++` with `orElse`, e.g.
      *   `a ++ b`
      * should become
      *   `a.orElse(b)`
      */
    final def ++(x: Parameters): Parameters = orElse(x)
  }

  object Parameters {

    /** Create a new empty Parameters object
      * @return
      */
    def empty: Parameters = new EmptyParameters

    /** Create a new Parameters object from a lookup function.
      * The arguments to the lookup function are (site, here, up) => { case ... => ... }
      *
      * @param f Function to create a new parameters object
      * @return
      */
    def apply(f: (View, View, View) => PartialFunction[Any, Any]): Parameters =
      new PartialParameters(f)
  }

  /** Configs are concrete user-extensible parameter objects.
    * They have overidden the toString method to be the class name.
    * @param p
    */
  class Config(p: Parameters) extends Parameters {
    def this(f: (View, View, View) => PartialFunction[Any, Any]) =
      this(Parameters(f))

    protected[config] def chain[T](
      site:  View,
      here:  View,
      up:    View,
      pname: Field[T]
    ) = p.chain(site, here, up, pname)
    override def toString = this.getClass.getSimpleName
    def toInstance = this
  }

  // Internal implementation:

  private class TerminalView extends View {
    def find[T](pname: Field[T]): Option[T] = pname.default
  }

  private class ChainView(head: Parameters, site: View, up: View) extends View {
    def find[T](pname: Field[T]) = head.chain(site, this, up, pname)
  }

  private class ChainParameters(x: Parameters, y: Parameters) extends Parameters {
    def chain[T](site: View, here: View, up: View, pname: Field[T]) = {
      x.chain(site, here, new ChainView(y, site, up), pname)
    }
  }

  private class EmptyParameters extends Parameters {
    def chain[T](site: View, here: View, up: View, pname: Field[T]) =
      up.find(pname)
  }

  private class PartialParameters(
    f: (View, View, View) => PartialFunction[Any, Any])
      extends Parameters {
    protected[config] def chain[T](
      site:  View,
      here:  View,
      up:    View,
      pname: Field[T]
    ) = {
      val g = f(site, here, up)
      if (g.isDefinedAt(pname)) Some(g.apply(pname).asInstanceOf[T])
      else up.find(pname)
    }
  }

  private class MapParameters(map: Map[Any, Any]) extends Parameters {
    protected[config] def chain[T](
      site:  View,
      here:  View,
      up:    View,
      pname: Field[T]
    ) = {
      val g = map.get(pname)
      if (g.isDefined) Some(g.get.asInstanceOf[T]) else up.find(pname)
    }
  }
}

package top

import L2cache.{CacheParameters, InclusiveCacheMicroParameters, InclusiveCacheParameters_lite}
import chisel3.util._

object parameters { //notice log2Ceil(4) returns 2.that is ,n is the total num, not the last idx.
  def num_sm = 2
  var num_warp = 8
  var num_thread = 32
  val SINGLE_INST: Boolean = false
  val SPIKE_OUTPUT: Boolean = true
  val INST_CNT: Boolean = true
  val INST_CNT_2: Boolean = false
  val GVM_ENABLED: Boolean = sys.env.getOrElse("RTL_GVM_ENABLED", "false").toBoolean
  val MMU_ENABLED: Boolean = false
  def MMU_ASID_WIDTH = mmu.SV32.asidLen
  val wid_to_check = 2
  def num_bank = 4                  // # of banks for register file
  def num_collectorUnit = num_warp
  def num_vgpr:Int = 128*num_warp
  def num_sgpr:Int = 256*num_warp
  def depth_regBank = log2Ceil(num_vgpr/num_bank)
  def regidx_width = 5

  def regext_width = 3

  def num_cluster = 1

  def num_sm_in_cluster = num_sm / num_cluster
  def depth_warp = if (num_warp == 1) 1 else log2Ceil(num_warp)

  // for register file bank access only, in operand collector
  // Calculate the highest slice index, ensuring it does not exceed the actual width of 'wid'
  def widSliceHigh = scala.math.min(log2Ceil(num_bank) - 1, depth_warp - 1)

  def depth_thread = log2Ceil(num_thread)

  def num_fetch = 2
  Predef.assert((num_fetch & (num_fetch - 1)) == 0, "num_fetch should be power of 2")

  def icache_align = num_fetch * 4

  def num_issue = 1

  def size_ibuffer = 2

  def xLen = 32 // data length 32-bit

  def instLen = 32

  def addrLen = 32

  def num_block = 8// not bigger than num_warp

  def num_warp_in_a_block = num_warp

  def num_lane = num_thread // 2

  def num_icachebuf = 1 //blocking for each warp

  def depth_icachebuf = log2Ceil(num_icachebuf)

  def num_ibuffer = 2

  def depth_ibuffer = log2Ceil(num_ibuffer)

  def lsu_num_entry_each_warp = 4 //blocking for each warp

  def lsu_nMshrEntry = num_warp // less than num_warp

  def dcache_NSets: Int = 256

  def dcache_NWays: Int = 2

  def dcache_BlockWords: Int = 32  // number of words per cacheline(block)
  def dcache_wshr_entry: Int = 4

  def dcache_SetIdxBits: Int = log2Ceil(dcache_NSets)

  def BytesOfWord = 32 / 8

  def dcache_WordOffsetBits = log2Ceil(BytesOfWord) //a Word has 4 Bytes

  def dcache_BlockOffsetBits = log2Ceil(dcache_BlockWords) // select word in block

  def dcache_TagBits = xLen - (dcache_SetIdxBits + dcache_BlockOffsetBits + dcache_WordOffsetBits)

  def dcache_MshrEntry: Int = 4

  def dcache_MshrSubEntry: Int = 2
  def num_sfu = (num_thread >> 2).max(1)

  def sharedmem_depth = 1024

  def sharedmem_BlockWords = dcache_BlockWords

  def sharemem_size = sharedmem_depth * sharedmem_BlockWords * 4 //bytes

  def l2cache_NSets: Int = 64

  def l2cache_NWays: Int = 16

  def l2cache_BlockWords: Int = dcache_BlockWords

  def l2cache_writeBytes: Int = 1

  def l2cache_memCycles: Int = 32

  def l2cache_portFactor: Int = 2

  def l1cache_sourceBits: Int = 3+log2Up(dcache_MshrEntry)+log2Up(dcache_NSets)

  def l2cache_cache = CacheParameters(2, l2cache_NWays, l2cache_NSets, num_l2cache, l2cache_BlockWords << 2, l2cache_BlockWords << 2)
  def l2cache_micro = InclusiveCacheMicroParameters(l2cache_writeBytes, l2cache_memCycles, l2cache_portFactor, num_warp, num_sm, num_sm_in_cluster, num_cluster,dcache_MshrEntry,dcache_NSets)
  def l2cache_micro_l = InclusiveCacheMicroParameters(l2cache_writeBytes, l2cache_memCycles, l2cache_portFactor, num_warp, num_sm, num_sm_in_cluster, 1,dcache_MshrEntry,dcache_NSets)
  def l2cache_params = InclusiveCacheParameters_lite(l2cache_cache, l2cache_micro, false, MMU_ENABLED)
  def l2cache_params_l = InclusiveCacheParameters_lite(l2cache_cache, l2cache_micro_l, false, MMU_ENABLED)

  def tc_dim: Seq[Int] = {
    var x: Seq[Int] = Seq(2, 2, 2)
    if (num_thread == 8)
      x = Seq(2, 4, 2)
    else if (num_thread == 32)
      x = Seq(4, 8, 4)
    x
  }

  def sig_length = 33

  def num_cache_in_sm = 2

  def num_l2cache = 1

  def l1tlb_ways = 8

  val LDS_BASE = 0x70000000  // LDS base address: a hyperparameter used within each SM

  def NUMBER_CU = num_sm
  def NUMBER_VGPR_SLOTS = num_vgpr
  def NUMBER_SGPR_SLOTS = num_sgpr
  def NUMBER_LDS_SLOTS = sharemem_size //TODO:check LDS max value. 128kB -> 2^17
  def WG_ID_WIDTH = 32
  def WF_COUNT_MAX = num_warp // max num of wf in a cu
  def WF_COUNT_PER_WG_MAX = num_warp_in_a_block // max num of wf in a wg
  def WAVE_ITEM_WIDTH = 10
  def MEM_ADDR_WIDTH = 32
  def CU_ID_WIDTH = log2Ceil(NUMBER_CU)
  def VGPR_ID_WIDTH = log2Ceil(NUMBER_VGPR_SLOTS)
  def SGPR_ID_WIDTH = log2Ceil(NUMBER_SGPR_SLOTS)
  def LDS_ID_WIDTH = log2Ceil(NUMBER_LDS_SLOTS)
  def WF_COUNT_WIDTH = log2Ceil(WF_COUNT_MAX + 1)
  def WF_COUNT_WIDTH_PER_WG = log2Ceil(WF_COUNT_PER_WG_MAX + 1)
  def TAG_WIDTH = CTA_SCHE_CONFIG.WG.WF_TAG_WIDTH_UINT
  def NUM_WG_DIM = 1024
  def NUM_WG_X = NUM_WG_DIM // max wg num in kernel
  def NUM_WG_Y = NUM_WG_DIM
  def NUM_WG_Z = NUM_WG_DIM
  def WG_SIZE_X_WIDTH = log2Ceil(NUM_WG_X + 1)
  def WG_SIZE_Y_WIDTH = log2Ceil(NUM_WG_Y + 1)
  def WG_SIZE_Z_WIDTH = log2Ceil(NUM_WG_Z + 1)

  def KNL_ASID_WIDTH = MMU_ASID_WIDTH

  object CTA_SCHE_CONFIG {
    import chisel3._
    object GPU {
      val NUM_CU = num_sm
      val MEM_ADDR_WIDTH = parameters.MEM_ADDR_WIDTH.W
      val NUM_WG_SLOT = num_block                  // Number of WG slot in each CU
      val NUM_WF_SLOT = num_warp                   // Number of WF slot in each CU
      val NUM_THREAD = num_thread                  // Number of thread in each WF
      val MMU_ENABLE = MMU_ENABLED                 // if MMU will be used
      val ASID_WIDTH = MMU_ASID_WIDTH.W            // MMU ASID width
    }
    object WG {
