  io.externalFlushPipe.bits:=Mux(warp_sche.io.flush.valid,warp_sche.io.flush.bits,warp_sche.io.flushCache.bits)

  csrfile.io.lsu_wid:=lsu.io.csr_wid
  lsu.io.csr_pds:=csrfile.io.lsu_pds
